def find_substring(s, words):
    word_len = len(words[0])
    num_words = len(words)
    total_len = word_len * num_words
    n = len(s)
    need = {}
    for w in words:
        need[w] = need.get(w, 0) + 1
    result = []
    for start in range(n - total_len + 1):
        seen = {}
        ok = True
        for i in range(num_words):
            piece = s[start + i * word_len: start + (i + 1) * word_len]      # slice out the i-th word-sized chunk directly
            if piece not in need:
                ok = False
                break
            seen[piece] = seen.get(piece, 0) + 1
            if seen[piece] > need[piece]:
                ok = False
                break
        if ok:
            result.append(start)
    return result


if __name__ == "__main__":
    print(find_substring("barfoothefoobarman", ["foo", "bar"]))

