import java.util.*;

public class Main {
    List<Integer> findSubstring(String s, String[] words) {
        int wordLen = words[0].length();
        int numWords = words.length;
        int totalLen = wordLen * numWords;
        int n = s.length();
        Map<String, Integer> need = new HashMap<>();
        for (String w : words) need.merge(w, 1, Integer::sum);
        List<Integer> result = new ArrayList<>();
        for (int start = 0; start + totalLen <= n; start++) {
            Map<String, Integer> seen = new HashMap<>();
            boolean ok = true;
            for (int i = 0; i < numWords; i++) {
                String piece = s.substring(start + i * wordLen, start + (i + 1) * wordLen);   // slice out the i-th word-sized chunk directly
                if (!need.containsKey(piece)) { ok = false; break; }
                seen.merge(piece, 1, Integer::sum);
                if (seen.get(piece) > need.get(piece)) { ok = false; break; }
            }
            if (ok) result.add(start);
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findSubstring("barfoothefoobarman", new String[]{"foo", "bar"}));
    }
}

