#include <bits/stdc++.h>
using namespace std;

vector<int> findSubstring(string s, vector<string>& words) {
    int wordLen = (int)words[0].size();
    int numWords = (int)words.size();
    int totalLen = wordLen * numWords;
    int n = (int)s.size();
    unordered_map<string,int> need;
    for (auto& w : words) need[w]++;
    vector<int> result;
    for (int start = 0; start + totalLen <= n; start++) {
        unordered_map<string,int> seen;
        bool ok = true;
        for (int i = 0; i < numWords; i++) {
            string piece = s.substr(start + i * wordLen, wordLen);                          // slice out the i-th word-sized chunk directly
            if (!need.count(piece)) { ok = false; break; }
            if (++seen[piece] > need[piece]) { ok = false; break; }
        }
        if (ok) result.push_back(start);
    }
    return result;
}

int main() {
    string s = "barfoothefoobarman";
    vector<string> words = {"foo", "bar"};
    vector<int> res = findSubstring(s, words);
    for (int x : res) cout << x << " ";
    cout << endl;
    return 0;
}

