import java.util.*;

public class Main {
    List<Integer> findSubstring(String s, String[] wordsArr) {
        int wordLen = wordsArr[0].length();
        int numWords = wordsArr.length;
        int n = s.length();
        Map<String, Integer> need = new HashMap<>();
        for (String w : wordsArr) need.merge(w, 1, Integer::sum);
        List<Integer> result = new ArrayList<>();
        for (int offset = 0; offset < wordLen; offset++) {                        // try every possible word-boundary alignment
            int left = offset;
            int count = 0;
            Map<String, Integer> window = new HashMap<>();
            for (int right = offset; right + wordLen <= n; right += wordLen) {
                String piece = s.substring(right, right + wordLen);
                if (need.containsKey(piece)) {
                    window.merge(piece, 1, Integer::sum);
                    count++;
                    while (window.get(piece) > need.get(piece)) {                   // too many of this word, shrink from the left
                        String leftPiece = s.substring(left, left + wordLen);
                        window.merge(leftPiece, -1, Integer::sum);
                        left += wordLen;
                        count--;
                    }
                    if (count == numWords) {                                        // every word matched exactly, record this start
                        result.add(left);
                        String leftPiece = s.substring(left, left + wordLen);
                        window.merge(leftPiece, -1, Integer::sum);
                        left += wordLen;
                        count--;
                    }
                } else {
                    window.clear();                                                  // a totally foreign word breaks any alignment through it
                    count = 0;
                    left = right + wordLen;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findSubstring("barfoothefoobarman", new String[]{"foo", "bar"}));
    }
}

