vector<int> findSubstring(string s, vector<string>& wordsArr) {
    int wordLen = (int)wordsArr[0].size();
    int numWords = (int)wordsArr.size();
    int n = (int)s.size();
    unordered_map<string,int> need;
    for (auto& w : wordsArr) need[w]++;
    vector<int> result;
    for (int offset = 0; offset < wordLen; offset++) {                         // try every possible word-boundary alignment
        int left = offset;
        int count = 0;
        unordered_map<string,int> window;
        for (int right = offset; right + wordLen <= n; right += wordLen) {
            string piece = s.substr(right, wordLen);
            if (need.count(piece)) {
                window[piece]++;
                count++;
                while (window[piece] > need[piece]) {                            // too many of this word, shrink from the left
                    string leftPiece = s.substr(left, wordLen);
                    window[leftPiece]--;
                    left += wordLen;
                    count--;
                }
                if (count == numWords) {                                          // every word matched exactly, record this start
                    result.push_back(left);
                    string leftPiece = s.substr(left, wordLen);
                    window[leftPiece]--;
                    left += wordLen;
                    count--;
                }
            } else {
                window.clear();                                                    // a totally foreign word breaks any alignment through it
                count = 0;
                left = right + wordLen;
            }
        }
    }
    return result;
}

int main() {
    string s = "barfoothefoobarman";
    vector<string> words = {"foo", "bar"};
    vector<int> res = findSubstring(s, words);
    for (int x : res) cout << x << " ";
    cout << endl;
    return 0;
